starter.css:
.pass { border: 1px solid #c9c4dc; border-radius: 12px; padding: 12px 16px; display: grid; gap: 8px; justify-items: start; }
.pass h2 { margin: 0; font-size: 1.2rem; }
.pass p { margin: 0; }
.btn { background: #5b3cc4; color: #fff; border: 0; border-radius: 8px; padding: 8px 16px; font: inherit; cursor: pointer; }
.text-btn { background: none; border: 0; padding: 0; font: inherit; color: #5b3cc4; text-decoration: underline; cursor: pointer; }
.link { color: #5b3cc4; text-decoration: underline; cursor: pointer; }

starter.js:
let count = 0;
function addToBasket() {
  count += 1;
  document.querySelector('#basket-count').textContent = String(count);
}
function removeFromBasket() {
  count = Math.max(0, count - 1);
  document.querySelector('#basket-count').textContent = String(count);
}

